import{b as e,O as d,g as r,j as a}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"产品上线","description":"","frontmatter":{},"headers":[],"relativePath":"testing/appendix/product-launch/index.md","filePath":"测试理论与实践/7.附录：模板与核心概念/06.产品上线.md","lastUpdated":1781538561000}'),n={name:"testing/appendix/product-launch/index.md"};function o(s,t,l,i,h,g){return d(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="产品上线" tabindex="-1">产品上线 <a class="header-anchor" href="#产品上线" aria-label="Permalink to &quot;产品上线&quot;">​</a></h1><blockquote><p>测试报告写了&quot;可以上线&quot;，然后呢？上线不是把代码推到生产环境就完了——它是一套有检查、有节奏、有退路、有监控的流程。</p></blockquote><h2 id="产品上线在测试交付链路中的位置" tabindex="-1">产品上线在测试交付链路中的位置 <a class="header-anchor" href="#产品上线在测试交付链路中的位置" aria-label="Permalink to &quot;产品上线在测试交付链路中的位置&quot;">​</a></h2><p>测试活动的终点不是&quot;测完&quot;，而是&quot;安全上线并验证通过&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求 → 开发 → 提测 → 测试执行 → 测试报告（建议上线）→ 产品上线 → 线上验证 → 持续监控</span></span>
<span class="line"><span>                                   ↑  本文件覆盖这一段  ↑</span></span></code></pre></div><blockquote><p>测试报告给出的是&quot;基于测试环境的质量结论&quot;，而产品上线是在生产环境中把这份结论变成现实的最后一公里。</p></blockquote><hr><h2 id="一、上线前检查清单" tabindex="-1">一、上线前检查清单 <a class="header-anchor" href="#一、上线前检查清单" aria-label="Permalink to &quot;一、上线前检查清单&quot;">​</a></h2><p>上线不是拍脑袋决定的——每一项都要确认到位才能点&quot;发布&quot;按钮。</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>检查项</th><th>一句话</th><th style="text-align:center;">谁来确认</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>测试报告结论</strong></td><td>测试报告明确写了&quot;建议上线&quot;吗？</td><td style="text-align:center;">测试负责人</td></tr><tr><td style="text-align:center;">2</td><td><strong>遗留缺陷评估</strong></td><td>未修复的 Bug 有哪些？有没有规避方案？影响范围可控吗？</td><td style="text-align:center;">测试 + 产品</td></tr><tr><td style="text-align:center;">3</td><td><strong>回归测试通过</strong></td><td>最后一轮回归有没有新增问题？核心链路全绿吗？</td><td style="text-align:center;">测试</td></tr><tr><td style="text-align:center;">4</td><td><strong>性能基准达标</strong></td><td>关键接口的 P95/P99 是否满足上线标准？</td><td style="text-align:center;">测试/运维</td></tr><tr><td style="text-align:center;">5</td><td><strong>数据备份完成</strong></td><td>数据库、配置文件、旧版本包是否已备份？</td><td style="text-align:center;">DBA/运维</td></tr><tr><td style="text-align:center;">6</td><td><strong>回滚方案就绪</strong></td><td>出问题怎么回退？谁来操作？预计多久恢复？</td><td style="text-align:center;">运维 + 开发</td></tr><tr><td style="text-align:center;">7</td><td><strong>监控告警配置</strong></td><td>核心指标（错误率、响应时间、业务量）的告警阈值配好了吗？</td><td style="text-align:center;">运维</td></tr><tr><td style="text-align:center;">8</td><td><strong>值班人员确认</strong></td><td>上线后谁盯着？联系方式都通吗？</td><td style="text-align:center;">项目经理</td></tr><tr><td style="text-align:center;">9</td><td><strong>上线公告已发</strong></td><td>用户、运营、客服知道要上线/维护吗？</td><td style="text-align:center;">产品/项目经理</td></tr></tbody></table><blockquote><p>8 和 9 看起来和测试无关，但上线出了问题找不到人或客服被打爆，这些都是测试环节没闭环的表现。测试有责任推动这些确认到位。</p></blockquote><hr><h2 id="二、上线执行节奏" tabindex="-1">二、上线执行节奏 <a class="header-anchor" href="#二、上线执行节奏" aria-label="Permalink to &quot;二、上线执行节奏&quot;">​</a></h2><p>上线不是&quot;全量一推了之&quot;，而是在放量过程中逐步验证、逐层兜底。</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:center;">放量比例</th><th style="text-align:center;">观察时间</th><th>做什么</th><th>通过标准</th></tr></thead><tbody><tr><td><strong>灰度发布</strong></td><td style="text-align:center;">1%~5%</td><td style="text-align:center;">≥ 30 分钟</td><td>推给少量真实用户，观察错误率、核心业务指标</td><td>无新增 5xx，核心链路成功率不变</td></tr><tr><td><strong>小流量放量</strong></td><td style="text-align:center;">10%~30%</td><td style="text-align:center;">≥ 1 小时</td><td>扩大用户范围，对比新旧版本的关键指标</td><td>性能无劣化，业务转化率无下降</td></tr><tr><td><strong>全量发布</strong></td><td style="text-align:center;">100%</td><td style="text-align:center;">—</td><td>全量推送，持续监控</td><td>错误率、响应时间平稳</td></tr></tbody></table><blockquote><p>每进入下一阶段前，必须确认上一阶段的监控数据正常。任何阶段出现问题，立即暂停发布、评估是否回滚。</p></blockquote><h3 id="常见的上线策略" tabindex="-1">常见的上线策略 <a class="header-anchor" href="#常见的上线策略" aria-label="Permalink to &quot;常见的上线策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适用场景</th><th style="text-align:center;">回滚难度</th></tr></thead><tbody><tr><td><strong>滚动发布</strong></td><td>逐个/逐批替换实例，新旧短暂共存</td><td>无状态服务、实例多</td><td style="text-align:center;">低</td></tr><tr><td><strong>蓝绿部署</strong></td><td>旧环境（蓝）和新环境（绿）并存，切换流量</td><td>需要快速回滚的场景</td><td style="text-align:center;">极低</td></tr><tr><td><strong>金丝雀发布</strong></td><td>先放一小部分流量到新版本，验证后再全量</td><td>高风险变更、核心链路</td><td style="text-align:center;">低</td></tr><tr><td><strong>功能开关</strong></td><td>代码部署到所有节点，通过开关控制功能可见性</td><td>需要按用户/区域逐步放开</td><td style="text-align:center;">极低</td></tr></tbody></table><blockquote><p>功能开关（Feature Flag）是实现最细粒度控制的策略——出问题关开关即可，不需要回滚代码。推荐高风险功能优先考虑这种方式。</p></blockquote><hr><h2 id="三、上线后验证" tabindex="-1">三、上线后验证 <a class="header-anchor" href="#三、上线后验证" aria-label="Permalink to &quot;三、上线后验证&quot;">​</a></h2><p>代码推上去不等于上线完成，线上验证才是真正&quot;交卷&quot;的时刻。</p><h3 id="_3-1-线上冒烟测试" tabindex="-1">3.1 线上冒烟测试 <a class="header-anchor" href="#_3-1-线上冒烟测试" aria-label="Permalink to &quot;3.1 线上冒烟测试&quot;">​</a></h3><p>在生产环境快速跑一遍核心用户流程，确认功能在真实环境中正常：</p><table tabindex="0"><thead><tr><th>验证项</th><th>做法</th><th style="text-align:center;">谁来测</th></tr></thead><tbody><tr><td><strong>核心链路</strong></td><td>登录→核心操作→退出，完整走通</td><td style="text-align:center;">测试</td></tr><tr><td><strong>新功能</strong></td><td>本次上线的功能在生产环境再跑一遍</td><td style="text-align:center;">测试/产品</td></tr><tr><td><strong>数据落库</strong></td><td>关键操作产生的数据是否正确写入数据库</td><td style="text-align:center;">测试/开发</td></tr><tr><td><strong>第三方依赖</strong></td><td>支付、短信、推送等外部服务是否正常调用</td><td style="text-align:center;">测试/开发</td></tr></tbody></table><blockquote><p>线上冒烟和测试环境的冒烟目的不同：测试环境冒烟是判断&quot;能不能往下测&quot;，线上冒烟是判断&quot;能不能让用户用&quot;。</p></blockquote><h3 id="_3-2-监控指标盯盘" tabindex="-1">3.2 监控指标盯盘 <a class="header-anchor" href="#_3-2-监控指标盯盘" aria-label="Permalink to &quot;3.2 监控指标盯盘&quot;">​</a></h3><p>上线后至少盯以下指标 30 分钟以上，确认平稳后再撤：</p><table tabindex="0"><thead><tr><th>监控维度</th><th>关键指标</th><th>告警阈值</th></tr></thead><tbody><tr><td><strong>服务健康</strong></td><td>5xx 错误率、服务可用率</td><td>5xx 率 &gt; 0.1% 或环比翻倍</td></tr><tr><td><strong>响应时间</strong></td><td>P95/P99 延迟</td><td>P95 延迟环比上涨 &gt; 50%</td></tr><tr><td><strong>业务指标</strong></td><td>登录成功率、下单量、支付成功率</td><td>关键转化率环比下跌 &gt; 10%</td></tr><tr><td><strong>资源指标</strong></td><td>CPU、内存、磁盘 IO</td><td>CPU &gt; 80%、内存持续增长</td></tr><tr><td><strong>日志异常</strong></td><td>Error 级别日志量、异常堆栈</td><td>出现新类型异常或 Error 量翻倍</td></tr></tbody></table><blockquote><p>上线后&quot;看着没问题的 30 分钟&quot;比上线本身更重要。很多问题不是在发布瞬间爆发，而是在流量慢慢上去之后才暴露。</p></blockquote><hr><h2 id="四、回滚决策" tabindex="-1">四、回滚决策 <a class="header-anchor" href="#四、回滚决策" aria-label="Permalink to &quot;四、回滚决策&quot;">​</a></h2><p>上线出了问题不可怕，可怕的是犹豫不决——每一分钟都在影响真实用户。</p><h3 id="什么情况要回滚" tabindex="-1">什么情况要回滚 <a class="header-anchor" href="#什么情况要回滚" aria-label="Permalink to &quot;什么情况要回滚&quot;">​</a></h3><table tabindex="0"><thead><tr><th>严重程度</th><th>症状</th><th>动作</th></tr></thead><tbody><tr><td><strong>P0 立即回滚</strong></td><td>核心链路不可用、大量 5xx、数据错乱、资金异常</td><td>停止发布，立即回滚，同步通知相关方</td></tr><tr><td><strong>P1 紧急评估</strong></td><td>非核心功能异常、部分用户受影响、性能明显劣化</td><td>暂停放量，15 分钟内决定回滚还是修复</td></tr><tr><td><strong>P2 记录跟进</strong></td><td>UI 显示异常、非关键功能偶发报错</td><td>暂不回滚，记录 Bug、评估下个版本修复</td></tr></tbody></table><h3 id="回滚的四要素" tabindex="-1">回滚的四要素 <a class="header-anchor" href="#回滚的四要素" aria-label="Permalink to &quot;回滚的四要素&quot;">​</a></h3><p>回滚方案不能只是&quot;有个脚本&quot;——必须是<strong>谁、怎么做、多久、什么信号</strong>四个要素都明确：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>谁执行   → 值班运维 / 开发负责人，联系方式已在检查清单确认</span></span>
<span class="line"><span>怎么做   → 流量切回旧环境（蓝绿）/ 执行回滚脚本 / 功能开关关闭</span></span>
<span class="line"><span>多久恢复 → 从决策到完成回滚的目标时间（建议 &lt; 5 分钟）</span></span>
<span class="line"><span>什么信号 → 什么条件下触发回滚（见上表 P0 条件）</span></span></code></pre></div><blockquote><p>回滚方案写在文档里不等于可用——上线前至少做过一次回滚演练，确认能跑通。</p></blockquote><hr><h2 id="五、上线复盘" tabindex="-1">五、上线复盘 <a class="header-anchor" href="#五、上线复盘" aria-label="Permalink to &quot;五、上线复盘&quot;">​</a></h2><p>每次上线后（无论顺利还是翻车），花一点时间做复盘，积累经验：</p><table tabindex="0"><thead><tr><th>复盘维度</th><th>顺利上线</th><th>出问题的上线</th></tr></thead><tbody><tr><td><strong>时间线</strong></td><td>各阶段实际耗时 vs 预期</td><td>从出现问题到发现、定位、决策、恢复的时间线</td></tr><tr><td><strong>问题根因</strong></td><td>—</td><td>根本原因是什么（代码、配置、环境、流程）</td></tr><tr><td><strong>发现方式</strong></td><td>监控哪些指标最先确认了正常</td><td>问题是谁发现的（监控告警 → 自动？用户投诉 → 被动？）</td></tr><tr><td><strong>响应效率</strong></td><td>流程有没有可以更快的环节</td><td>从发现到恢复的每一步有没有可缩短的空间</td></tr><tr><td><strong>改进措施</strong></td><td>这次顺利的经验能不能固化</td><td>如何防止同类问题再发生（测试覆盖、监控、流程）</td></tr></tbody></table><p>复盘的产物不是一份&quot;吸取教训&quot;的文档，而是<strong>至少一个具体的待办项</strong>——比如&quot;核心链路的线上冒烟用例补充到自动化脚本&quot;&quot;XX 接口的 P95 延迟告警阈值从 500ms 调到 300ms&quot;。</p><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li><strong>上线前 9 项检查</strong>——测试结论、遗留缺陷、回归结果、性能达标、数据备份、回滚方案、监控告警、值班确认、上线公告，每一项都要有人确认</li><li><strong>上线要分阶段放量</strong>——灰度 → 小流量 → 全量，每阶段验证通过再进入下一阶段，出问题随时暂停</li><li><strong>上线后至少盯 30 分钟</strong>——线上冒烟核心链路 + 监控五大维度（服务健康、响应时间、业务指标、资源、日志）</li><li><strong>回滚标准要前置</strong>——P0 立即回滚的条件在执行前就约定好，不要在出问题时才讨论&quot;要不要回&quot;</li><li><strong>功能开关是最灵活的上线策略</strong>——高风险功能优先考虑，出问题关开关即可，回滚成本几乎为零</li><li><strong>复盘要产出一个具体待办</strong>——不是写完文档就结束，至少要有一个能改的项落到下一轮迭代里</li></ol>`,47)])])}const u=e(n,[["render",o]]);export{p as __pageData,u as default};
